import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps);
"""


_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <limits>
#include <cstdint>
#include <cute/tensor.hpp>

// CUTE names are qualified explicitly to avoid nvcc anonymous-namespace collisions.

namespace {

constexpr int kThreads = 256;

__global__ void cute_layer_norm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int64_t rows,
    int64_t normalized_size,
    float eps)
{
    const int row = static_cast<int>(blockIdx.x);
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp_id = tid >> 5;
    constexpr int kWarps = kThreads / 32;
    if (row >= rows) {
        return;
    }
    const int64_t row_offset = static_cast<int64_t>(row) * normalized_size;
    auto gx = cute::make_tensor(
        cute::make_gmem_ptr(x + row_offset),
        cute::make_shape(normalized_size),
        cute::make_stride(cute::Int<1>{}));
    auto gw = cute::make_tensor(
        cute::make_gmem_ptr(weight),
        cute::make_shape(normalized_size),
        cute::make_stride(cute::Int<1>{}));
    auto gb = cute::make_tensor(
        cute::make_gmem_ptr(bias),
        cute::make_shape(normalized_size),
        cute::make_stride(cute::Int<1>{}));
    auto go = cute::make_tensor(
        cute::make_gmem_ptr(out + row_offset),
        cute::make_shape(normalized_size),
        cute::make_stride(cute::Int<1>{}));
    extern __shared__ double reduction[];
    double* sums = reduction;
    double* sumsq = reduction + kWarps;
    double local_sum = 0.0;
    double local_sumsq = 0.0;
    const bool vectorized =
        (normalized_size % 4 == 0) &&
        ((reinterpret_cast<uintptr_t>(x + row_offset) & 15u) == 0) &&
        ((reinterpret_cast<uintptr_t>(weight) & 15u) == 0) &&
        ((reinterpret_cast<uintptr_t>(bias) & 15u) == 0);
    if (vectorized) {
        const float4* x4 = reinterpret_cast<const float4*>(x + row_offset);
        const int64_t vector_count = normalized_size / 4;
        for (int64_t i = tid; i < vector_count; i += blockDim.x) {
            const float4 v = x4[i];
            local_sum += static_cast<double>(v.x);
            local_sum += static_cast<double>(v.y);
            local_sum += static_cast<double>(v.z);
            local_sum += static_cast<double>(v.w);
            local_sumsq += static_cast<double>(v.x) * static_cast<double>(v.x);
            local_sumsq += static_cast<double>(v.y) * static_cast<double>(v.y);
            local_sumsq += static_cast<double>(v.z) * static_cast<double>(v.z);
            local_sumsq += static_cast<double>(v.w) * static_cast<double>(v.w);
        }
    } else {
        for (int64_t i = tid; i < normalized_size; i += blockDim.x) {
            const double v = static_cast<double>(gx(i));
            local_sum += v;
            local_sumsq += v * v;
        }
    }
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
        local_sumsq += __shfl_down_sync(0xffffffff, local_sumsq, offset);
    }
    if (lane == 0) {
        sums[warp_id] = local_sum;
        sumsq[warp_id] = local_sumsq;
    }
    __syncthreads();
    if (warp_id == 0) {
        double block_sum = lane < kWarps ? sums[lane] : 0.0;
        double block_sumsq = lane < kWarps ? sumsq[lane] : 0.0;
        for (int offset = 16; offset > 0; offset >>= 1) {
            block_sum += __shfl_down_sync(0xffffffff, block_sum, offset);
            block_sumsq += __shfl_down_sync(0xffffffff, block_sumsq, offset);
        }
        if (lane == 0) {
            sums[0] = block_sum;
            sumsq[0] = block_sumsq;
        }
    }
    __syncthreads();
    const double mean = sums[0] / static_cast<double>(normalized_size);
    double variance =
        sumsq[0] / static_cast<double>(normalized_size) - mean * mean;
    if (variance < 0.0) {
        variance = 0.0;
    }
    const double inv_std = rsqrt(variance + static_cast<double>(eps));
    if (vectorized) {
        const float4* x4 = reinterpret_cast<const float4*>(x + row_offset);
        float4* out4 = reinterpret_cast<float4*>(out + row_offset);
        const float4* weight4 = reinterpret_cast<const float4*>(weight);
        const float4* bias4 = reinterpret_cast<const float4*>(bias);
        const int64_t vector_count = normalized_size / 4;
        for (int64_t i = tid; i < vector_count; i += blockDim.x) {
            const float4 xv = x4[i];
            const float4 wv = weight4[i];
            const float4 bv = bias4[i];
            float4 ov;
            ov.x = static_cast<float>((static_cast<double>(xv.x) - mean) * inv_std * static_cast<double>(wv.x) + static_cast<double>(bv.x));
            ov.y = static_cast<float>((static_cast<double>(xv.y) - mean) * inv_std * static_cast<double>(wv.y) + static_cast<double>(bv.y));
            ov.z = static_cast<float>((static_cast<double>(xv.z) - mean) * inv_std * static_cast<double>(wv.z) + static_cast<double>(bv.z));
            ov.w = static_cast<float>((static_cast<double>(xv.w) - mean) * inv_std * static_cast<double>(wv.w) + static_cast<double>(bv.w));
            out4[i] = ov;
        }
    } else {
        for (int64_t i = tid; i < normalized_size; i += blockDim.x) {
            const double normalized =
                (static_cast<double>(gx(i)) - mean) * inv_std;
            go(i) = static_cast<float>(
                normalized * static_cast<double>(gw(i)) +
                static_cast<double>(gb(i)));
        }
    }
}

} // namespace

torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    TORCH_CHECK(
        x.scalar_type() == at::kFloat &&
        weight.scalar_type() == at::kFloat &&
        bias.scalar_type() == at::kFloat,
        "cute_layer_norm currently expects float32 tensors");

    TORCH_CHECK(x.dim() >= 1, "x must have at least one dimension");
    TORCH_CHECK(weight.dim() == 1, "weight must be one-dimensional");
    TORCH_CHECK(bias.dim() == 1, "bias must be one-dimensional");
    TORCH_CHECK(
        weight.numel() == bias.numel(),
        "weight and bias must have the same number of elements");

    const int64_t normalized_size = weight.numel();
    TORCH_CHECK(normalized_size > 0,
                "normalized size must be positive");
    TORCH_CHECK(
        x.numel() % normalized_size == 0,
        "The input size must be divisible by the normalized size");

    auto x_contiguous = x.contiguous();
    auto weight_contiguous = weight.contiguous();
    auto bias_contiguous = bias.contiguous();
    auto out = torch::empty_like(x_contiguous);

    const int64_t rows = x_contiguous.numel() / normalized_size;

    TORCH_CHECK(rows <= static_cast<int64_t>(std::numeric_limits<int>::max()),
                "Too many rows for the CUDA grid");

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_layer_norm_kernel<<<
        static_cast<unsigned int>(rows),
        kThreads,
        2 * (kThreads / 32) * sizeof(double),
        stream>>>(
        x_contiguous.data_ptr<float>(),
        weight_contiguous.data_ptr<float>(),
        bias_contiguous.data_ptr<float>(),
        out.data_ptr<float>(),
        rows,
        normalized_size,
        static_cast<float>(eps));

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "cute_layer_norm_kernel launch failed");

    return out;
}
"""


_cute_ext = load_inline(
    name="cute_layer_norm_ext",
    cpp_sources=_cpp_decl,
    cuda_sources=_cuda_src,
    functions=["cute_layer_norm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        normalized_size = self.ln.weight.numel()
        x_view = x.reshape(-1, normalized_size)

        return _cute_ext.cute_layer_norm(
            x_view,
            self.ln.weight.reshape(-1),
            self.ln.bias.reshape(-1),
            self.ln.eps,
        ).reshape_as(x)

